#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <ucontext.h>

static void handler(int sig, siginfo_t *si, void *uc)
{
	ucontext_t *u = (ucontext_t *)uc;
	unsigned long pc = (unsigned long)u->uc_mcontext.pc;
	char buf[256];
	int n;

	n = snprintf(buf, sizeof buf, "=== %s addr=%p pc=%#lx ===\n",
		     sig == SIGSEGV ? "SIGSEGV" : "SIGBUS", si->si_addr, pc);
	write(2, buf, n);

	FILE *f = fopen("/proc/self/maps", "r");
	if (f) {
		char line[512];
		while (fgets(line, sizeof line, f)) {
			unsigned long a, b;
			char perms[8];
			if (sscanf(line, "%lx-%lx %7s", &a, &b, perms) == 3 &&
			    pc >= a && pc < b)
				write(2, line, strlen(line));
		}
		fclose(f);
	}
	_exit(139);
}

__attribute__((constructor)) static void segv_init(void)
{
	struct sigaction sa;
	memset(&sa, 0, sizeof sa);
	sa.sa_sigaction = handler;
	sa.sa_flags = SA_SIGINFO | SA_NODEFER;
	sigaction(SIGSEGV, &sa, NULL);
	sigaction(SIGBUS, &sa, NULL);
}

