#define _GNU_SOURCE
#include <signal.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <ucontext.h>

struct mapent {
	unsigned long start, end;
	char perms[8];
	char path[256];
};

static int nmaps;
static struct mapent maps[256];

static unsigned long hexval(const char **p)
{
	unsigned long v = 0;
	int c;
	while ((c = **p)) {
		if (c >= '0' && c <= '9')
			v = v * 16 + (c - '0');
		else if (c >= 'a' && c <= 'f')
			v = v * 16 + (c - 'a' + 10);
		else if (c >= 'A' && c <= 'F')
			v = v * 16 + (c - 'A' + 10);
		else
			break;
		(*p)++;
	}
	return v;
}

static void load_maps(void)
{
	char buf[131072];
	int fd = open("/proc/self/maps", O_RDONLY);
	ssize_t got;
	char *line, *end;

	nmaps = 0;
	if (fd < 0)
		return;
	got = read(fd, buf, sizeof buf - 1);
	close(fd);
	if (got <= 0)
		return;
	buf[got] = 0;
	line = buf;
	end = buf + got;
	while (line < end && nmaps < (int)(sizeof maps / sizeof maps[0])) {
		char *nl = strchr(line, '\n');
		const char *p = line;
		struct mapent *m = &maps[nmaps];
		int i = 0;

		if (nl)
			*nl = 0;
		m->start = hexval(&p);
		if (*p == '-') {
			p++;
			m->end = hexval(&p);
		}
		while (*p == ' ')
			p++;
		while (*p && *p != ' ' && i < 7)
			m->perms[i++] = *p++;
		m->perms[i] = 0;
		m->path[0] = 0;
		{
			const char *slash = strrchr(line, '/');
			if (slash) {
				strncpy(m->path, slash, sizeof m->path - 1);
				m->path[sizeof m->path - 1] = 0;
			}
		}
		nmaps++;
		if (!nl)
			break;
		line = nl + 1;
	}
}

static struct mapent *find(unsigned long v)
{
	int i;
	for (i = 0; i < nmaps; i++)
		if (v >= maps[i].start && v < maps[i].end)
			return &maps[i];
	return NULL;
}

static void emit(const char *tag, unsigned long v)
{
	struct mapent *m;
	char b[320];
	int n;

	m = find(v);
	if (!m)
		return;
	n = snprintf(b, sizeof b, "%s %#lx %s+%#lx\n", tag, v,
		     m->path[0] ? m->path : "[anon]", v - m->start);
	write(2, b, n);
}

static void handler(int sig, siginfo_t *si, void *uc)
{
	ucontext_t *u = (ucontext_t *)uc;
	unsigned long pc = (unsigned long)u->uc_mcontext.pc;
	unsigned long sp = (unsigned long)u->uc_mcontext.sp;
	unsigned long lr = (unsigned long)u->uc_mcontext.regs[30];
	char buf[160];
	int n, i;

	n = snprintf(buf, sizeof buf, "=== %s addr=%p pc=%#lx sp=%#lx lr=%#lx\n",
		     sig == SIGSEGV ? "SIGSEGV" : "SIGBUS", si->si_addr, pc, sp, lr);
	write(2, buf, n);

	load_maps();
	emit("PC ", pc);
	emit("LR ", lr);
	for (i = 0; i < 48; i++) {
		unsigned long v = ((unsigned long *)sp)[i];
		emit("STK", v);
	}
	_exit(139);
}

__attribute__((constructor)) static void segv_init(void)
{
	struct sigaction sa;
	memset(&sa, 0, sizeof sa);
	sa.sa_sigaction = handler;
	sa.sa_flags = SA_SIGINFO | SA_NODEFER;
	sigaction(SIGSEGV, &sa, NULL);
	sigaction(SIGBUS, &sa, NULL);
}

