	uidev.absmin[ABS_Y] = 0; uidev.absmax[ABS_Y] = 1279;
	uidev.absmin[ABS_MT_POSITION_X] = 0; uidev.absmax[ABS_MT_POSITION_X] = 719;
	uidev.absmin[ABS_MT_POSITION_Y] = 0; uidev.absmax[ABS_MT_POSITION_Y] = 1279;
